var i=`0334-mousse-au-chocolat`;var o=`world-0334`;var a=`FR`;var r=`western-europe`;var n=4;var s=168;var l={en:`Mousse au Chocolat`,ua:`Шоколадний мус`};var h={en:`A traditional France dish made with heavy cream, pasteurized egg whites. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: вершки високої жирності, пастеризовані яєчні білки. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Melt chocolate gently over a barely simmering water bath together with a splash of cream, stirring smooth; cool to lukewarm.`,ua:`Обережно розтопіть шоколад із невеликою кількістю вершків на водяній бані, помішуючи до гладкості; остудіть до ледь теплого стану.`,t:[`melting-chocolate`],m:6,i:[[`dark-chocolate`,260,`g`],[`heavy-cream`,80,`ml`]]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:7,i:[[`heavy-cream`,400,`ml`],[`white-granulated-sugar`,55,`g`]]},{en:`Fold lightly whipped cream into cooled melted chocolate, then gently fold in pasteurized whipped egg whites to make an airy mousse; portion into serving dishes.`,ua:`Обережно введіть злегка збиті вершки в охолоджений шоколад, тоді додайте збиті пастеризовані білки до пухкого мусу й розподіліть по креманках.`,t:[`folding-batter`],m:5,i:[[`pasteurized-egg-whites`,120,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 150 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 150 хвилин.`,t:[`rapid-chilling`],m:150,i:[]}];var d={slug:i,id:o,country:`FR`,region:r,servings:4,minutes:168,title:l,text:h,steps:g};export{a as country,d as default,o as id,s as minutes,r as region,n as servings,i as slug,g as steps,h as text,l as title};